mapper.update:
update cms_counter
   set counter_nm = #{c.counterNm}, unit_nm = #{c.unitNm}, use_yn = #{c.useYn}, remark = #{c.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where counter_id = #{c.counterId} and row_ver = #{c.rowVer}

mapper.select:
select x.*, c.scale from (
    select r.reading_id, r.read_at, r.gauge_value, r.delta_qty, r.reset_yn, r.source, r.remark, r.recorded_at, r.recorded_by,
           r.void_yn, r.void_reason, r.voided_by, r.voided_at, r.counter_id,
           case when r.void_yn = 'N' then sum(case when r.void_yn = 'N' then r.delta_qty else 0 end)
                over (order by r.read_at, r.reading_id rows between unbounded preceding and current row) end as cumulative
      from cms_counter_reading r where r.counter_id = #{counterId}
) x join cms_counter c on c.counter_id = x.counter_id
 order by x.read_at desc, x.reading_id desc
 limit #{limit}
